(()=>{'use strict';
const originalAdmin=adminHTML,originalRender=render;let templatesList=[],templateArchived=false,templateLoaded=false,loadingTemplates=false,logFilters={},logPage=1,logResult=null,logSeq=0,noticeSeq=0;
const activeAdmin=()=>serverMode&&role==='admin'&&!db.scopedBusiness&&!publicPage;
const time=t=>new Date(t).toLocaleString('ar-SA',{timeZone:'Asia/Riyadh'});
function businessCards(){return db.accounts.map(a=>{const base=db.shops.find(s=>s.id===a.shop);if(!base)return '';const cards=db.shops.filter(s=>(s.business||s.id)===a.shop&&!s.archivedAt),status=statusOf(a),clients=cards.reduce((n,s)=>n+s.members.length,0),employees=(base.employees||[]).filter(e=>e.status==='active').length;return `<article class="panel"><div class="panel-head"><h2>${esc(base.name)}</h2><span class="pill ${status==='active'?'':'gray'}">${esc(statusNames[status])}</span></div><p class="sub">${fmt(cards.length)} برامج ولاء · ${fmt(clients)} عضويات عملاء · ${fmt(employees)} موظفون نشطون</p><div class="actions"><button class="btn secondary" data-action="open-user" data-id="${esc(a.id)}">عرض اللوحة</button><button class="btn quiet" data-admin-account="${esc(a.id)}">إدارة الحساب والاشتراك</button></div></article>`;}).join('');}
function overview(){const enabled=db.accounts.filter(a=>statusOf(a)==='active').length,cards=db.shops.filter(s=>!s.archivedAt);return head('إدارة رِجعة','منصتك، في نظرة واحدة.','الحسابات والاشتراكات وبرامج الولاء الفعلية.')+`<div id="admin-alerts" aria-live="polite"></div><div class="stats">${[[db.accounts.length,'حسابات الأنشطة'],[enabled,'اشتراكات مفعّلة'],[cards.length,'برامج الولاء'],[cards.reduce((n,s)=>n+s.members.length,0),'عضويات العملاء']].map(([n,title])=>`<article class="stat"><div class="stat-top">${title}</div><div class="stat-value">${fmt(n)}</div></article>`).join('')}</div><div class="grid-two">${businessCards()}</div>`;}
function templateHTML(){return head('قوالب المنصة','مكتبة قوالب الولاء','قوالب مستقلة؛ تعديلها لا يغيّر بطاقات العملاء أو يصدر تحديثًا للمحفظة.',`<button class="btn primary" data-admin-template="new">إضافة قالب</button>`)+`<section class="panel"><div class="actions"><button class="btn secondary" data-admin-template="list-active" aria-pressed="${!templateArchived}">القوالب المتاحة</button><button class="btn quiet" data-admin-template="list-archived" aria-pressed="${templateArchived}">المؤرشفة</button></div><div id="platform-template-results" class="grid-two mt">جارٍ تحميل القوالب…</div></section>`;}
async function loadTemplates(){if(loadingTemplates)return;loadingTemplates=true;try{const j=await api('/api/admin/templates?archived='+(templateArchived?'1':'0'));templatesList=j.templates;templateLoaded=true;const box=document.querySelector('#platform-template-results');if(!box)return;box.innerHTML=templatesList.length?templatesList.map(t=>`<article class="panel"><h2>${esc(t.title)}</h2><p>${esc(t.card.reward)} · ${fmt(t.card.target)} زيارات</p><div class="admin-template-swatch" style="background:${/^#[a-f0-9]{6}$/i.test(t.card.color)?t.card.color:'#204b3c'};color:${/^#[a-f0-9]{6}$/i.test(t.card.accent)?t.card.accent:'#fff'}">${icon(t.card.icon)}<span>${esc(t.card.name)}</span></div><small class="sub">آخر تحديث: ${esc(time(t.updated))}</small><div class="actions mt">${t.archived?`<button class="btn secondary" data-admin-template="restore" data-id="${esc(t.id)}">استعادة</button>`:`<button class="btn secondary" data-admin-template="edit" data-id="${esc(t.id)}">تعديل القالب</button><button class="btn quiet" data-admin-template="use" data-id="${esc(t.id)}">استخدام لبطاقة جديدة</button><button class="btn quiet" data-admin-template="archive" data-id="${esc(t.id)}">أرشفة</button>`}</div></article>`).join(''):'<p class="empty">لا توجد قوالب في هذه القائمة.</p>';}catch(e){const box=document.querySelector('#platform-template-results');if(box)box.textContent=e.message;}finally{loadingTemplates=false;}}
function editor(t){const c=t?.card||{name:'بطاقة ولاء',category:'متجر',reward:'مكافأة مجانية',terms:'زيارة لكل عملية شراء مؤهلة. تحدد شروط النشاط تفاصيل المكافأة.',color:'#204b3c',accent:'#e7efcf',target:4,icon:'coffee'};modal(t?'تعديل القالب':'إضافة قالب',`<form id="admin-template-form" data-id="${esc(t?.id||'')}" data-version="${t?.version||0}"><p class="sub">تعديل القالب يؤثر على البطاقات الجديدة المختارة منه فقط.</p>${[['title','عنوان القالب',t?.title||''],['name','اسم التصميم',c.name],['category','نوع النشاط',c.category],['reward','المكافأة',c.reward]].map(([n,label,v])=>`<label class="field"><span>${label}</span><input class="input" name="${n}" maxlength="${n==='title'?80:120}" required value="${esc(v)}"></label>`).join('')}<label class="field"><span>عدد الزيارات</span><input class="input" type="number" min="2" max="12" name="target" value="${c.target}" required></label><label class="field"><span>الرمز</span><select name="icon">${[['coffee','قهوة'],['car','سيارة'],['bag','متجر'],['scissors','صالون'],['star','نجمة'],['heart','قلب']].map(([id,label])=>`<option value="${id}" ${c.icon===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="grid-two"><label class="field">لون البطاقة<input name="color" type="color" value="${esc(c.color)}"></label><label class="field">لون العناصر<input name="accent" type="color" value="${esc(c.accent)}"></label></div><label class="field"><span>شروط الولاء</span><textarea class="input" name="terms" maxlength="1500" required>${esc(c.terms)}</textarea></label><p id="admin-template-error" role="alert"></p><button class="btn primary full" type="submit">حفظ القالب</button></form>`);}
const optionAccounts=()=>'<option value="">جميع الحسابات</option>'+db.accounts.map(a=>`<option value="${esc(a.id)}" ${logFilters.account===a.id?'selected':''}>${esc(a.name)}</option>`).join('');
function logsHTMLAdmin(kind){return head('سجلات المنصة',kind==='audit'?'سجل الإدارة':'عمليات الأنشطة','ابحث وراجع جميع الصفحات؛ الأوقات بتوقيت الرياض.')+`<section class="panel"><form id="admin-log-filter" class="admin-filter-grid"><label class="field">بحث<input class="input" name="q" value="${esc(logFilters.q||'')}" maxlength="120" placeholder="العميل أو العملية أو المعرّف"></label><label class="field">الحساب<select name="account">${optionAccounts()}</select></label>${kind==='operations'?`<label class="field">البطاقة<select name="shop"><option value="">جميع البطاقات</option>${db.shops.filter(s=>!logFilters.account||db.accounts.find(a=>a.id===logFilters.account)?.shop===(s.business||s.id)).map(s=>`<option value="${esc(s.id)}" ${logFilters.shop===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="field">الفرع<select name="branch"><option value="">جميع الفروع</option>${db.shops.flatMap(s=>(s.branches||[]).map(b=>`<option value="${esc(b.id)}" ${logFilters.branch===b.id?'selected':''}>${esc(s.name+' · '+b.name)}</option>`)).join('')}</select></label>`:''}<label class="field">المنفذ<input class="input" name="actor" maxlength="120" value="${esc(logFilters.actor||'')}"></label><label class="field">من تاريخ<input class="input" type="date" name="from" value="${esc(logFilters.from||'')}"></label><label class="field">إلى تاريخ<input class="input" type="date" name="to" value="${esc(logFilters.to||'')}"></label><div class="actions"><button type="submit" class="btn primary">بحث</button><button type="button" class="btn quiet" data-admin-log="reset">مسح التصفية</button></div></form><div id="admin-log-results" aria-live="polite">جارٍ تحميل السجل…</div></section>`;}
async function loadLogs(){const seq=++logSeq,kind=view==='adminlog'?'audit':'operations',params=new URLSearchParams({...logFilters,page:String(logPage),kind});try{const data=await api('/api/admin/logs?'+params);if(seq!==logSeq||!activeAdmin()||!['activity','adminlog'].includes(view))return;logResult=data;logPage=data.page;const box=document.querySelector('#admin-log-results');if(!box)return;box.innerHTML=`<p class="sub">${fmt(data.total)} عملية مطابقة</p><div class="table-wrap"><table><thead><tr><th>الوقت</th><th>النشاط / العميل</th><th>العملية</th><th>المنفذ</th>${kind==='operations'?'<th>البطاقة والفرع</th>':''}</tr></thead><tbody>${data.rows.length?data.rows.map(l=>`<tr><td>${esc(time(l.time))}</td><td>${esc(l.user||l.name||'—')}</td><td>${esc(l.caption)}<small class="line-meta">${esc(l.detail||'')}</small></td><td>${esc(l.actor)}</td>${kind==='operations'?`<td>${esc(l.shopName)}<small class="line-meta">${esc(l.branchName)}</small></td>`:''}</tr>`).join(''):`<tr><td colspan="5">لا توجد نتائج مطابقة.</td></tr>`}</tbody></table></div><div class="actions mt"><button class="btn secondary" data-admin-log="prev" ${data.page<=1?'disabled':''}>السابق</button><span>${fmt(data.page)} / ${fmt(Math.max(1,Math.ceil(data.total/data.pageSize)))}</span><button class="btn secondary" data-admin-log="next" ${data.page*data.pageSize>=data.total?'disabled':''}>التالي</button><button class="btn quiet" data-admin-log="export" ${!data.rows.length?'disabled':''}>تصدير الصفحة</button></div>`;}catch(e){if(seq===logSeq){const box=document.querySelector('#admin-log-results');if(box)box.textContent=e.message;}}}
async function notices(){if(!activeAdmin()||document.hidden)return;const seq=++noticeSeq;try{const [support,health]=await Promise.all([api('/api/support/summary'),api('/api/operations/status')]);if(seq!==noticeSeq||!activeAdmin())return;const link=document.querySelector('[data-support-link]');if(link){link.querySelector('.admin-support-badge')?.remove();if(support.unread)link.insertAdjacentHTML('beforeend',`<span class="admin-support-badge" aria-label="${fmt(support.unread)} تذاكر غير مقروءة">${fmt(support.unread)}</span>`);}const issues=[];if(support.unread)issues.push(`<a href="/support.html">${fmt(support.unread)} تذاكر تحتاج المتابعة</a>`);if(!health.backup.encrypted)issues.push('تشفير النسخ غير مفعّل');if(!health.backup.external?.configured)issues.push('التخزين الخارجي للنسخ لم يُربط بعد');if(health.backup.external?.failure)issues.push('تعذر رفع آخر نسخة خارجية');if(health.backup.failure)issues.push('تعذر إنشاء آخر نسخة احتياطية');const box=document.querySelector('#admin-alerts');if(box)box.innerHTML=issues.length?`<div class="notice"><strong>تحتاج متابعة</strong><ul>${issues.map(x=>`<li>${x}</li>`).join('')}</ul></div>`:'<p class="sub">لا توجد تنبيهات تشغيل تحتاج المتابعة.</p>';}catch{/* Existing page remains usable during transient status failures. */}}
adminHTML=function(){if(!serverMode||db.scopedBusiness)return originalAdmin();if(view==='overview')return overview();if(view==='shops')return head('أنشطة المنصة','حسابات الأنشطة','افتح معاينة النشاط أو انتقل لإدارة اشتراكه.')+`<div class="grid-two">${businessCards()}</div>`;if(view==='templates')return templateHTML();if(view==='activity'||view==='adminlog')return logsHTMLAdmin(view==='adminlog'?'audit':'operations');return originalAdmin();};
render=function(){originalRender();if(!activeAdmin())return;if(view==='templates')loadTemplates();if(['activity','adminlog'].includes(view))loadLogs();notices();};
document.addEventListener('submit',async e=>{if(!activeAdmin())return;const f=e.target;if(f.id==='admin-log-filter'){e.preventDefault();e.stopImmediatePropagation();logFilters=Object.fromEntries(new FormData(f));logPage=1;await loadLogs();return;}if(f.id!=='admin-template-form')return;e.preventDefault();e.stopImmediatePropagation();const button=f.querySelector('button[type=submit]');button.disabled=true;try{const d=Object.fromEntries(new FormData(f));const {title,...c}=d;await api('/api/admin/templates',{action:'save',id:f.dataset.id||undefined,version:Number(f.dataset.version),title,card:{...c,target:Number(c.target),programType:'visits'}});document.querySelector('#modal').close();await loadTemplates();toast('تم حفظ القالب دون تعديل بطاقات العملاء.');}catch(err){document.querySelector('#admin-template-error').textContent=err.message;}finally{button.disabled=false;}},true);
document.addEventListener('click',async e=>{if(!activeAdmin())return;const b=e.target.closest('[data-admin-template],[data-admin-log],[data-admin-account]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();try{if(b.dataset.adminAccount){view='accounts';render();const search=document.querySelector('#account-search');if(search){search.value=b.dataset.adminAccount;search.dispatchEvent(new Event('input',{bubbles:true}));}return;}const t=templatesList.find(x=>x.id===b.dataset.id),a=b.dataset.adminTemplate;if(a==='new')editor(null);if(a==='edit'&&t)editor(t);if(a==='list-active'||a==='list-archived'){templateArchived=a==='list-archived';render();}if((a==='archive'||a==='restore')&&t){b.disabled=true;await api('/api/admin/templates',{action:a,id:t.id,version:t.version});await loadTemplates();}if(a==='use'&&t){modal('إنشاء بطاقة من القالب',`<form id="admin-template-use-form" data-template="${esc(t.id)}"><p>ستنشأ بطاقة جديدة ضمن حدود الباقة. راجع تصميمها قبل حفظه؛ لا تتغير أي بطاقة موجودة.</p><label class="field">الحساب<select name="account">${db.accounts.filter(acc=>statusOf(acc)==='active').map(acc=>`<option value="${esc(acc.id)}">${esc(acc.name)}</option>`).join('')}</select></label><label class="field">اسم البطاقة<input class="input" name="name" maxlength="36" required></label><p id="admin-template-use-error" role="alert"></p><button class="btn primary" type="submit">إنشاء ومراجعة التصميم</button></form>`);}
const action=b.dataset.adminLog;if(action==='prev'||action==='next'){logPage+=action==='next'?1:-1;await loadLogs();}if(action==='reset'){logFilters={};logPage=1;render();}if(action==='export'&&logResult){const cell=v=>'"'+String(v||'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"',lines=[['الوقت','النشاط','العملية','المنفذ','الفرع'],...logResult.rows.map(l=>[time(l.time),l.user||l.name,l.caption,l.actor,l.branchName])],blob=new Blob(['\ufeff'+lines.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='rg3h-log-page-'+logPage+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(err){toast(err.message);}finally{b.disabled=false;}},true);
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='admin-template-use-form'||!activeAdmin())return;e.preventDefault();e.stopImmediatePropagation();const t=templatesList.find(x=>x.id===f.dataset.template),d=new FormData(f),a=db.accounts.find(x=>x.id===d.get('account'));if(!t||!a)return;const b=f.querySelector('button');b.disabled=true;try{const scoped=await api('/api/state?scope='+encodeURIComponent(a.shop)+'&shop='+encodeURIComponent(a.shop));const created=await api('/api/command',{action:'create-program',shop:a.shop,scope:a.shop,name:d.get('name'),type:'visits'});acceptServer(created);role='owner';view='design';draft={...structuredClone(shop().card),...structuredClone(t.card),name:String(d.get('name')),title:String(d.get('name'))};document.querySelector('#modal').close();resetWorkspaceFilters();render();toast('أُنشئت البطاقة الجديدة. راجع التصميم ثم احفظه.');}catch(err){document.querySelector('#admin-template-use-error').textContent=err.message;}finally{b.disabled=false;}},true);
setInterval(()=>notices(),60000);render();
})();
